head.script:
scwin.checkVal = function() {
    return filterOpt.key == '/^[a-z]/';
}
scwin.unitTest = function() {
    // Init test
    WebSquare.wUnit.start();
    // Test step 1: 1. Source 탭에서 filterOpt.key = new RegExp("^[a-z]") 인지 확인한다.
    // - 1. In the Source tab, verify that filterOpt.key = new RegExp ("^ [a-z]").
    WebSquare.wUnit.addCommand("pause", "1000");
    // Verify 1: 1. filterOpt.key = new RegExp("^[a-z]") -- 1. filterOpt.key = new RegExp ("^ [a-z]")
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    // Test step 2: 2. 브라우저에서 확인한다. - 2. Check in the browser.
    // Verify 2: 2. abv, bba, yyy 값이 정상으로 보여진다. -- 2. The abv, bba, yyy values are shown as normal.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('grid1_cell_0_2').childNodes[0].innerHTML == 'abv'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('grid1_cell_1_2').childNodes[0].innerHTML == 'bba'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('grid1_cell_2_2').childNodes[0].innerHTML == 'yyy'", "true");
    WebSquare.wUnit.addCommand("pause", "1000");
    // Run test
    WebSquare.wUnit.run();
    // Stop test
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    grid1.setData(["", "", "abv", ""], "append");
    grid1.setData(["", "", "CzC", ""], "append");
    grid1.setData(["", "", "bba", ""], "append");
    grid1.setData(["", "", "yyy", ""], "append");
    window.filterOpt = {};
    filterOpt.type = 'regExp';
    filterOpt.colIndex = 'column8';
    //filterOpt.key = new RegExp('[a-z]'); 		 // 영소문자로 구성 : 정상작동
    filterOpt.key = new RegExp('^[a-z]'); // 영소문자로 시작 : 정상작동하지 않음.
    filterOpt.condition = 'and';
    grid1.setColumnFilter(filterOpt);
    // Function test
    // Created by Sang.Do
    // Created date 17-Jan-2018
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
